        if (match) return "显示已提交 (" + match[1] + ")";

        match = normalized.match(/^(?:Show\s+more|显示更多)\s*[（(]\s*(\d+)\s*[)）]$/i);
        if (match) return "显示更多 (" + match[1] + ")";
        return null;
